#!/usr/bin/env python3
# Generator for the lamella-tls-roots bundle from the official curl/Mozilla CA store
# (https://curl.se/ca/cacert.pem, fetched in-session -- not committed). Emits two artifacts:
#
#   src/roots.der  -- every root certificate's DER, concatenated (a flat blob include_bytes!'d).
#   src/bundle.rs  -- @generated: a compact index sorted by SUBJECT DN, for the lazy trusted-cert
#                     callback to find a root by a child certificate's ISSUER DN without parsing
#                     the whole store into the device's small mbedTLS pool.
#
# Clean-room: derived from the official CA data (facts: a public CA's certificate + its subject
# name), not from any implementation. Regenerate when the bundle is refreshed.
#
# Usage: python gen_roots.py [cacert.pem]   (defaults to cacert.pem beside this script)
import os, sys
from cryptography import x509
from cryptography.hazmat.primitives.serialization import Encoding

HERE = os.path.dirname(os.path.abspath(__file__))
PEM = sys.argv[1] if len(sys.argv) > 1 else os.path.join(HERE, "cacert.pem")
SRC = os.path.normpath(os.path.join(HERE, "..", "src"))

pem_bytes = open(PEM, "rb").read()
certs = x509.load_pem_x509_certificates(pem_bytes)

# The bundle's own "as of" snapshot line, carried into the crate so firmware/tooling can warn
# when the baked store is stale (roots are added, distrusted, and expire over time).
snapshot = "unknown"
for line in pem_bytes.decode("ascii", "replace").splitlines():
    marker = "Certificate data from Mozilla as of:"
    if marker in line:
        snapshot = line.split(marker, 1)[1].strip().rstrip("#").strip()
        break

# (subject_der, cert_der) for each root. subject_der is the DER of the RDNSequence Name -- the exact
# bytes mbedTLS exposes as child->issuer_raw / crt->subject_raw, so an issuer==subject match is a
# byte comparison. Sorted by subject_der so the callback binary-searches the equal-subject range.
entries = []
for cert in certs:
    subject_der = cert.subject.public_bytes()
    cert_der = cert.public_bytes(Encoding.DER)
    entries.append((subject_der, cert_der))
entries.sort(key=lambda e: e[0])

# The flat DER blob + per-entry (subject_der, offset, len) into it.
blob = bytearray()
index = []
for subject_der, cert_der in entries:
    offset = len(blob)
    blob.extend(cert_der)
    index.append((subject_der, offset, len(cert_der)))

os.makedirs(SRC, exist_ok=True)
with open(os.path.join(SRC, "roots.der"), "wb") as f:
    f.write(blob)


def byte_literal(data):
    return 'b"' + "".join(f"\\x{b:02x}" for b in data) + '"'


lines = [
    "// @generated by gen/gen_roots.py from the official curl/Mozilla CA bundle (cacert.pem);",
    "// do not edit by hand -- regenerate instead. The DER lives in roots.der (include_bytes!);",
    "// this is the SUBJECT-DN index, sorted for a binary search by a child's issuer DN.",
    "",
    "/// The upstream bundle's \"Certificate data from Mozilla as of\" snapshot -- the store ages",
    "/// (roots are added, distrusted, and expire), so a long-lived device should refresh it or",
    "/// pin its own certificate instead.",
    f'pub(crate) static MOZILLA_SNAPSHOT: &str = "{snapshot}";',
    "",
    "/// The concatenated DER of every bundled root certificate.",
    'pub(crate) static ROOT_DER: &[u8] = include_bytes!("roots.der");',
    "",
    "/// `(subject_dn_der, offset, len)` for each root, sorted by `subject_dn_der`. The offset/len",
    "/// slice `ROOT_DER`; the subject DN is the exact bytes mbedTLS compares against a child's",
    "/// issuer DN, so a lookup is a binary search over these.",
    "pub(crate) static ROOT_INDEX: &[(&[u8], u32, u32)] = &[",
]
for subject_der, offset, length in index:
    lines.append(f"    ({byte_literal(subject_der)}, {offset}, {length}),")
lines.append("];")
lines.append("")

with open(os.path.join(SRC, "bundle.rs"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(lines))

print(f"roots: {len(entries)}")
print(f"roots.der bytes: {len(blob)}")
print(f"bundle.rs entries: {len(index)}")
